export function hasPersian(s: string): boolean {
  return FA_SCRIPT.test(s || '')
}

export function toLatinDigits(s: string): string {
  if (!s) return ''
  return s.replace(/[۰-۹٠-٩]/g, (d) => DIGIT_MAP[d] ?? d)
}

function normalizePunct(s: string): string {
  return s.replace(/[،؛؟٪٫٬ـ]/g, (c) => PUNCT_MAP[c] ?? '')
}

function boundedReplace(text: string, key: string, value: string): string {
  if (!key || !text.includes(key)) return text
  if (/[ ·•،/]/.test(key)) return text.split(key).join(value)
  let out = ''
  let i = 0
  while (i < text.length) {
    const idx = text.indexOf(key, i)
    if (idx < 0) {
      out += text.slice(i)
      break
    }
    out += text.slice(i, idx)
    const before = idx === 0 ? '' : text[idx - 1]
    const afterIdx = idx + key.length
    const after = afterIdx >= text.length ? '' : text[afterIdx]
    const glued =
      (before && FA_LETTER_BOUNDARY.test(before)) || (after && FA_LETTER_BOUNDARY.test(after))
    if (glued) {
      out += key
      i = idx + 1
    } else {
      out += value
      i = afterIdx
    }
  }
  return out
}

function sanitizeRemaining(text: string): string {
  let out = normalizePunct(toLatinDigits(text))
  out = out.replace(FA_LETTERS, (w) => {
    if (WORD_MAP[w]) return WORD_MAP[w]
    const plain = w.replace(/\u200c/g, '')
    if (WORD_MAP[plain]) return WORD_MAP[plain]
    for (const suf of ['‌ها', 'ها', 'های', 'ان', 'ات', 'ین', 'ون'] as const) {
      if (w.endsWith(suf)) {
        const stem = w.slice(0, -suf.length)
        if (WORD_MAP[stem]) return WORD_MAP[stem]
      }
    }
    return 'item'
  })
  out = normalizePunct(toLatinDigits(out)).replace(/[ \t]{2,}/g, ' ').trim()
  if (hasPersian(out)) {
    out = out.replace(FA_SCRIPT, '').replace(/[ \t]{2,}/g, ' ').trim() || 'item'
  }
  return out
}

/** Dynamic store / reducer strings with IDs or titles embedded. */
const DYNAMIC_FA_PATTERNS: Array<{ re: RegExp; to: (...m: string[]) => string }> = [
  { re: /^درخواست (.+) تایید شد\.$/, to: (_m, id) => `Purchase request ${id} approved.` },
  { re: /^درخواست (.+) رد شد\.$/, to: (_m, id) => `Purchase request ${id} rejected.` },
  { re: /^تراکنش (.+) تایید شد\.$/, to: (_m, id) => `Transaction ${id} approved.` },
  { re: /^تراکنش (.+) رد شد\.$/, to: (_m, id) => `Transaction ${id} rejected.` },
  { re: /^مکاتبه (.+) بسته شد\.$/, to: (_m, id) => `Correspondence ${id} closed.` },
  { re: /^کار پیگیری «(.+)» ایجاد شد\.$/, to: (_m, title) => `Follow-up work “${title}” was created.` },
  { re: /^کار «(.+)» به مرحله (.+) منتقل شد\.$/, to: (_m, title, stage) => `Work “${title}” moved to stage ${stage}.` },
  { re: /^درخواست توسط مدیرعامل تایید شد\.$/, to: () => 'Request approved by the CEO.' },
  { re: /^خرید تایید شد — در انتظار ورود$/, to: () => 'Purchase approved — awaiting receipt' },
  { re: /^وضعیت (.+) به «تایید شده» تغییر کرد\.$/, to: (_m, id) => `Status of ${id} changed to Approved.` },
  { re: /^تایید (.+)$/, to: (_m, id) => `Approved ${id}` },
  { re: /^هشدار تایید مشاهده شد\.$/, to: () => 'Alert acknowledged.' },
  { re: /^هشدار بسته شد\.$/, to: () => 'Alert closed.' },
  { re: /^پیام ارسال شد\.$/, to: () => 'Message sent.' },
]

/**
 * Ensure user-facing text contains no Persian/Arabic script when locale is English.
 * Never returns Persian script characters.
 */
export function ensureEnglish(input: string | null | undefined): string {
  if (input == null || input === '') return ''
  const raw = String(input)
  if (!hasPersian(raw)) return normalizePunct(toLatinDigits(raw))

  for (const { re, to } of DYNAMIC_FA_PATTERNS) {
    const m = raw.match(re)
    if (m) {
      const mapped = to(...m)
      // Recurse so embedded FA stage names still sanitize.
      return ensureEnglish(mapped)
    }
  }

  // exact dict lookup
  if (Object.prototype.hasOwnProperty.call(CURATED_EN, raw)) {
    return normalizePunct(toLatinDigits(CURATED_EN[raw] ?? ''))
  }
  if (Object.prototype.hasOwnProperty.call(FA_EN_DICT, raw)) {
    return normalizePunct(toLatinDigits(FA_EN_DICT[raw] ?? ''))
  }
  if (Object.prototype.hasOwnProperty.call(EXACT_ONLY, raw)) {
    return normalizePunct(toLatinDigits(EXACT_ONLY[raw] ?? ''))
  }

  // longest-key substring replacement
  let result = raw
  for (const key of SORTED_KEYS) {
    if (key && result.includes(key)) {
      result = boundedReplace(result, key, FA_EN_PHRASES[key] ?? FA_EN_DICT[key] ?? '')
    }
  }

  result = normalizePunct(toLatinDigits(result))
  if (hasPersian(result)) {
    result = sanitizeRemaining(result)
  }
  return result
}



/** Keys that must stay canonical (not phrase-translated) for logic / routing. */
const DEEP_SKIP_KEYS = new Set([
  'id',
  'src',
  'href',
  'to',
  'status',
  'priority',
  'stage',
  'recordType',
  'recordId',
  'unitId',
  'workId',
  'agentId',
  'purchaseRequestId',
  'threadId',
  'tab',
  'mode',
  'lane',
])

/** Deep-sanitize all string values for English-mode state projection. */
export function deepEnsureEnglish<T>(value: T, key?: string): T {
  if (value == null) return value
  if (typeof value === 'string') {
    if (key && DEEP_SKIP_KEYS.has(key)) {
      // Still neutralize Persian digits / accidental FA in skipped fields when present
      if (key === 'stage' || key === 'status' || key === 'priority' || key === 'id' || key === 'sku' || key?.endsWith('Id') || key === 'recordType') {
        return value as T
      }
      if (hasPersian(value)) return ensureEnglish(value) as T
      return value as T
    }
    if (key === 'src' || key === 'href' || key === 'to') return value
    return ensureEnglish(value) as T
  }
  if (typeof value === 'number' || typeof value === 'boolean') return value
  if (Array.isArray(value)) {
    return value.map((v) => deepEnsureEnglish(v)) as T
  }
  if (typeof value === 'object') {
    const out: Record<string, unknown> = {}
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      out[k] = deepEnsureEnglish(v, k)
    }
    return out as T
  }
  return value
}
